#include <bits/stdc++.h>
#include <atcoder/modint>
using namespace std;
using namespace atcoder;

using mint = modint998244353;

int main() {
	int n,p;
	cin >> n >> p;

	mint P=mint(p)/mint(100), Q=mint(1)-P;

	vector<mint>fact(n+1);
	fact[0]=mint(1);
	for(int i=1; i<=n; i++)fact[i]=fact[i-1]*mint(i);

	mint ans=0;
	for(int k=1;k<=n;k++){
		if(k>=(n-k))ans+=mint(k)*fact[k]/(fact[n-k]*fact[2*k-n])*P.pow(n-k)*Q.pow(2*k-n);
		if((k-1)>=(n-k))ans+=mint(k)*fact[k-1]/(fact[n-k]*fact[2*k-n-1])*P.pow(n-k+1)*Q.pow(2*k-n-1);		
	}
	cout << ans.val() <<endl;
	return 0;
}

#include <bits/stdc++.h>

#include <atcoder/modint>
using mint = atcoder::modint998244353;
using namespace std;

int main() {
    int n, p;
    cin >> n >> p;
    vector dp(n + 1, mint(0));
    mint critical = mint(p) / 100, normal = 1 - critical;
    for(int i = 1; i <= n; i++)
        dp[i] = (dp[max(0, i - 2)] * critical + dp[i - 1] * normal) + 1;
    cout << dp.back().val() << endl;
}

#include <bits/stdc++.h>

#include <atcoder/modint>
using mint = atcoder::modint998244353;
using namespace std;

template <class T>
struct matrix {
    int h, w;
    vector<vector<T>> e;
    matrix(int h_, int w_) : h(h_), w(w_), e(h_, vector<T>(w_)) {}
    std::vector<T> &operator[](int p) {
        return e[p];
    }
    const std::vector<T> &operator[](int p) const {
        return e[p];
    }
    matrix operator*(const matrix &m) {
        assert(w == m.h);
        matrix ret(h, m.w);
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < m.w; j++) {
                for(int k = 0; k < w; k++) {
                    ret[i][j] += e[i][k] * m[k][j];
                }
            }
        }
        return ret;
    }
    matrix operator^(long long p) const {
        assert(h == w);
        matrix I(h, w), b(*this);
        for(int i = 0; i < h; i++) I[i][i] = T(1);
        while(p) {
            if(p & 1) I = I * b;
            b = b * b;
            p >>= 1;
        }
        return I;
    }
};

int main() {
    int n, p;
    cin >> n >> p;
    mint critical = mint(p) / 100, normal = 1 - critical;
    matrix<mint> r(3, 1);
    r[0][0] = 1 + normal;
    r[1][0] = 1;
    r[2][0] = 1;
    matrix<mint> m(3, 3);
    m[0] = {normal, critical, 1};
    m[1] = {1, 0, 0};
    m[2] = {0, 0, 1};
    r = (m ^ (n - 1)) * r;
    cout << r[1][0].val() << endl;
}
